import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"GhostBrain — De Gemini a API","description":"Convierte una cuenta gratuita de Gemini en una API real compatible con OpenAI y Anthropic: sesiones seguras, pools multi-cuenta, streaming SSE.","frontmatter":{"title":"GhostBrain — De Gemini a API","description":"Convierte una cuenta gratuita de Gemini en una API real compatible con OpenAI y Anthropic: sesiones seguras, pools multi-cuenta, streaming SSE."},"headers":[],"relativePath":"es/projects/ghost-brain/index.md","filePath":"es/projects/ghost-brain/index.md"}`),a={name:`es/projects/ghost-brain/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="ghostbrain-—-de-gemini-a-api" tabindex="-1">GhostBrain — De Gemini a API <a class="header-anchor" href="#ghostbrain-—-de-gemini-a-api" aria-label="Permalink to “GhostBrain — De Gemini a API”">​</a></h1><p><strong><a href="https://github.com/Godde3s/GhostBrain" target="_blank" rel="noreferrer">GhostBrain</a></strong> resucita una cuenta web gratuita de Gemini como infraestructura real. La app web te da un modelo potente detrás de una página de chat; GhostBrain lo saca de ahí y lo sirve como una API de verdad — con todo lo que eso implica: vinculación segura de sesiones, pools multi-cuenta, streaming SSE y persistencia.</p><h2 id="decisiones-de-diseno" tabindex="-1">Decisiones de diseño <a class="header-anchor" href="#decisiones-de-diseno" aria-label="Permalink to “Decisiones de diseño”">​</a></h2><p>La parte frágil de cualquier puente de cuenta web es la sesión. GhostBrain la trata como ciudadano de primera clase: las cookies se guardan cifradas, las sesiones se chequean y rotan antes de morir —no después—, y las cuentas se agrupan en pools para que ninguna identidad absorba todo el tráfico. Cuando una sesión muere, el pool la marca en silencio y sigue sirviendo — tu cliente nunca ve un 401.</p><table tabindex="0"><thead><tr><th>Preocupación</th><th>Enfoque</th></tr></thead><tbody><tr><td>Seguridad de sesión</td><td>Bóveda de cookies cifrada, sin secretos en texto plano en disco.</td></tr><tr><td>Fiabilidad</td><td>Sondeos de salud en segundo plano + rotación automática.</td></tr><tr><td>Compatibilidad</td><td><code>/v1/chat/completions</code> de OpenAI y <code>/v1/messages</code> de Anthropic.</td></tr><tr><td>Streaming</td><td>Retransmisión SSE nativa, token por token.</td></tr><tr><td>Lenguaje</td><td>Python — I/O asíncrono de punta a punta.</td></tr></tbody></table><h2 id="donde-encaja-en-mi-stack" tabindex="-1">Dónde encaja en mi stack <a class="header-anchor" href="#donde-encaja-en-mi-stack" aria-label="Permalink to “Dónde encaja en mi stack”">​</a></h2><p>GhostBrain es el hermano en Python de <a href="/Usf/es/projects/glm-free-api/">GLM Free API</a>, y ambos son upstreams que mi <a href="/Usf/es/projects/omnirouter/">OmniRouter</a> balancea con gusto. Desplegados juntos en tiers gratuitos — Hugging Face Spaces, Railway, Render — me dan una flota de APIs multi-modelo cuya factura mensual es exactamente cero. Esa combinación es la que <a href="/Usf/es/projects/hermes-stack/">Hermes Stack</a> empaqueta como despliegue de un clic.</p><div class="tip custom-block"><p class="custom-block-title">Uso responsable</p><p>Los puentes de tiers gratuitos viven de la generosidad de otros. GhostBrain se auto-limita y rota cuentas precisamente para seguir siendo educado — úsalo como invitado, no como saqueador.</p></div>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};